#[derive(Debug, Clone)]
pub(crate) struct Native2dMcpCallFailure {
    code: String,
    message: String,
}

impl Native2dMcpCallFailure {
    fn new(code: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            code: code.into(),
            message: message.into(),
        }
    }

    pub(crate) fn code(&self) -> &str {
        &self.code
    }

    pub(crate) fn message(&self) -> &str {
        &self.message
    }

    fn typed(error: TypedDocumentAuthoringError) -> Self {
        Self::new(error.code(), error.to_string())
    }

    fn no_document(label: &str) -> Self {
        Self::new(
            "editor.native_2d_document_not_open",
            format!("no active {label} document is open in the Native 2D workspace"),
        )
    }
}

fn require_empty_arguments(arguments: Value) -> Result<(), Native2dMcpCallFailure> {
    match arguments {
        Value::Object(values) if values.is_empty() => Ok(()),
        other => Err(Native2dMcpCallFailure::new(
            "mcp.invalid_arguments",
            format!("tool expects an empty argument object, received {other}"),
        )),
    }
}

fn decode_mcp<T: DeserializeOwned>(arguments: Value) -> Result<T, Native2dMcpCallFailure> {
    serde_json::from_value(arguments).map_err(|error| {
        Native2dMcpCallFailure::new("mcp.invalid_arguments", error.to_string())
    })
}

fn mcp_value<T: Serialize>(value: T) -> Result<Value, Native2dMcpCallFailure> {
    serde_json::to_value(value).map_err(|error| {
        Native2dMcpCallFailure::new("mcp.result_serialization_failed", error.to_string())
    })
}

